'use strict';
const $=id=>document.getElementById(id);let packs=[],selected=new Set(),positions={},light=null;
try{selected=new Set(JSON.parse(localStorage.getItem('blooming-monster-shortlist')||'[]'))}catch(e){}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem('blooming-monster-shortlist',JSON.stringify([...selected]))}catch(e){$('toast').textContent='Browser storage unavailable; export your shortlist to keep it.'}}
function list(){return packs.flatMap(p=>p.names.filter(n=>selected.has(p.id+'|'+n)).map(n=>p.id+' · '+n+' — '+p.author+'\n'+p.url))}
function matches(p){let q=$('search').value.trim().toLowerCase(),f=$('filter').value;return (!q||[p.title,p.author,p.names.join(' '),p.animations,p.note,p.view].join(' ').toLowerCase().includes(q))&&(f==='all'||f==='top'&&p.view==='Top-down'||f==='artist'&&p.art==='Artist-made'||f==='undead'&&/skeleton|zombie|spectre|ghost|undead|mummy|lich|vampire|wraith/i.test(p.title+p.names.join(' '))||f==='shortlist'&&p.names.some(n=>selected.has(p.id+'|'+n)))}
function redraw(){const result=packs.filter(matches);$('count').textContent=result.length+' / '+packs.length+' packs shown · '+selected.size+' creatures shortlisted';$('shortlist').style.display=selected.size?'block':'none';$('shortlist').innerHTML='<strong>Your shortlist · review only</strong><p>'+[...selected].map(v=>esc(v.replace('|',' · '))).join(' &nbsp; / &nbsp; ')+'</p>';
$('grid').innerHTML=result.map(p=>{let image=p.images[positions[p.id]||0],partial=/no attack|no dedicated|idle only|only.*idle|unconfirmed|side-view|paid edition|not explicit/i.test(p.note+' '+p.animations+' '+p.view);return `<article class="card" id="${p.id}"><div class="preview"><span class="number">${p.id} · ORIGINAL PREVIEW</span>${image?`<img src="${esc(image)}" alt="${esc(p.title)} by ${esc(p.author)} — creator preview" loading="lazy" data-enlarge="${p.id}">`:'<span>Preview on creator page</span>'}${p.images.length>1?`<button class="prev" data-cycle="${p.id}" data-delta="-1" aria-label="Previous ${esc(p.title)} preview">←</button><button class="next" data-cycle="${p.id}" data-delta="1" aria-label="Next ${esc(p.title)} preview">${(positions[p.id]||0)+1}/${p.images.length} →</button>`:''}</div><div class="details"><div class="meta">${esc(p.author)} · FREE DOWNLOAD</div><h2>${esc(p.title)}</h2><div class="badges">${p.inUse?'<span class="badge">USED IN ROAD CAMPS</span>':''}<span class="badge ${p.view!=='Top-down'?'warn':''}">${esc(p.view)}</span><span class="badge ${p.art!=='Artist-made'?'warn':''}">${esc(p.art)}</span><span class="badge">${p.names.length} listed forms${p.colors?' + '+p.colors+' extra variants':''}</span></div><p class="anim">${esc(p.animations)}</p>${p.note?`<p class="note">${esc(p.note)}</p>`:''}<details><summary>View creatures & shortlist (${p.names.length})</summary><div class="variants">${p.names.map(n=>`<button data-select="${esc(p.id+'|'+n)}" class="${selected.has(p.id+'|'+n)?'active':''}" aria-pressed="${selected.has(p.id+'|'+n)}">${selected.has(p.id+'|'+n)?'★':'☆'} ${esc(n)}</button>`).join('')}</div></details><details><summary>Licence & credit notes</summary><p class="license">${esc(p.license)}</p></details><div class="links"><a class="source" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Creator & free download ↗</a></div></div></article>`}).join('')||'<div class="empty">No packs match. Try another search or filter.</div>';
$('grid').querySelectorAll('[data-cycle]').forEach(b=>b.onclick=()=>{const p=packs.find(x=>x.id===b.dataset.cycle);positions[p.id]=((positions[p.id]||0)+Number(b.dataset.delta)+p.images.length)%p.images.length;const card=b.closest('.card');card.querySelector('img').src=p.images[positions[p.id]];card.querySelector('.next').textContent=(positions[p.id]+1)+'/'+p.images.length+' →'});
$('grid').querySelectorAll('[data-enlarge]').forEach(img=>{img.onclick=()=>{light=packs.find(x=>x.id===img.dataset.enlarge);showLight();$('lightbox').showModal()};img.onerror=()=>{img.style.display='none';let x=document.createElement('span');x.textContent='Preview unavailable — open creator page';img.parentElement.appendChild(x)}});
$('grid').querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{let k=b.dataset.select;selected.has(k)?selected.delete(k):selected.add(k);save();let open=[...document.querySelectorAll('.card details[open]')].map(d=>[d.closest('.card').id,[...d.parentNode.querySelectorAll('details')].indexOf(d)]);redraw();for(let [id,n]of open){let card=document.getElementById(id);if(card)card.querySelectorAll('details')[n].open=true}})}
function showLight(){let i=positions[light.id]||0;$('lightimg').src=light.images[i];$('lighttitle').textContent=light.id+' · '+light.title+' · '+(i+1)+' / '+light.images.length;$('lightsource').href=light.url}
$('close').onclick=()=>$('lightbox').close();$('lightprev').onclick=()=>{positions[light.id]=((positions[light.id]||0)-1+light.images.length)%light.images.length;showLight()};$('lightnext').onclick=()=>{positions[light.id]=((positions[light.id]||0)+1)%light.images.length;showLight()};$('search').oninput=redraw;$('filter').onchange=redraw;$('clear').onclick=()=>{if(selected.size&&confirm('Clear your monster shortlist?')){selected.clear();save();redraw()}};
$('export').onclick=()=>{if(!selected.size){$('toast').textContent='Expand a pack and star a creature first.';return}let text='BLOOMING QUEST — MONSTER SHORTLIST\nReview preferences only; exporting does not change the monsters already in the game.\n\n'+list().join('\n\n');let blob=new Blob([text],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='blooming-quest-monster-shortlist.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
fetch('monster-catalog.json?v=17').then(r=>{if(!r.ok)throw Error('Could not load catalogue');return r.json()}).then(data=>{packs=data;$('packs').textContent=packs.length;$('forms').textContent=packs.reduce((n,p)=>n+p.names.length,0);$('colors').textContent=packs.reduce((n,p)=>n+p.colors,0);redraw()}).catch(e=>$('count').textContent=e.message+' — refresh to retry.');
